/* Example: styling an element with basic properties */
.box {
    width: 100px;
    height: 100px;
    background-color: #e74c3c;
    border: 3px solid #c0392b;
}

/* Example: adding a transition to an element */
.button {
    background-color: blue;
    transition: background-color 0.3s ease;
}

/* Example: hover effect for a button */
.button:hover {
    background-color: darkblue;
}

/* Example: targeting a single property */
.element {
  transition: opacity 0.5s linear;
}

/* Example: transitioning multiple properties */
.element {
    transition: width 0.3s ease, background-color 0.3s ease;
}
.element:hover {
    width: 200px;
    background-color: coral;
}

/* Example: adding a delay to a transition */
.element {
    transition: opacity 0.3s 0.5s ease-in;
}

/* Example: adding a timing function to a transition */
.element {
    transition: background-color 1s ease-in-out;
}

/* Shorthand transition example */
.element {
    transition: all 1s ease-in-out 0.2s;
}
